def sum_gp(a, n, r):
    """Write a function to find the sum of geometric progression series.

    Return the sum of the first ``n`` terms of the geometric
    progression with first term ``a`` and common ratio ``r``:

    ``a + a*r + a*r**2 + ... + a*r**(n-1)``
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if r == 1:
        return a * n
    if isinstance(a, int) and isinstance(r, int):
        # Exact integer arithmetic: (r**n - 1) is divisible by (r - 1).
        return a * (r**n - 1) // (r - 1)
    return a * (r**n - 1) / (r - 1)
